import json, struct
prog = currentProgram
out = {}
for a in ['0x142925904', '0x14295a0e8', '0x142934694', '0x142ad58e8', '0x142a7b658', '0x142925870', '0x142a7c88c', '0x1429edb90', '0x1429cd030', '0x1429258f4', '0x1429258f8', '0x1429258fc', '0x142a95db0', '0x142a877a0']:
    try:
        addr = prog.getAddressFactory().getAddress(a)
        buf = bytearray(8)
        prog.getMemory().getBytes(addr, buf)
        b = bytes(buf)
        out[a] = [round(struct.unpack("<f", b[i:i+4])[0], 6) for i in (0, 4)]
    except Exception as e:
        out[a] = "ERR:" + str(e)[:100]
print(json.dumps(out))
